fn w1(m: Arc<Mutex<bool>>, cv: Arc<Condvar>, g12: Arc<Semaphore>, g_n: Arc<Semaphore>) {
    let mut proceed = m.lock().unwrap();
    let _ = (&cv, &g12, &g_n);
    while !*proceed {
        proceed = cv.wait(proceed).unwrap();
    }
    drop(proceed);
    let _permit = g_n.acquire();
}

