fn w1(c: Arc<Mutex<i32>>) {
    let mut guard = c.lock().unwrap();
    if *guard < 1 {
        *guard += 1;
    }
    drop(guard);
}

fn w2(c: Arc<Mutex<i32>>) {
    let mut guard = c.lock().unwrap();
    if *guard < 1 {
